// mediaHarness bundles one test router over a fresh temp store plus the single
// library its seeded items belong to (libraries.uniq is (module_id, root_path),
// so one library per harness — items are distinguished by id).
type mediaHarness struct {
	h  http.Handler
	st *store.Store
}

// newMediaHarness builds the authed router for the media tests: a real store +
// the real middleware chain, exactly as production wires them (New).
func newMediaHarness(t *testing.T) mediaHarness {
	t.Helper()
	st := openAPIStore(t)
	if _, err := st.CreateLibrary(context.Background(), "tv", "/media/media-tests", "Media"); err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	h := New(Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
		return scan.Result{}, nil
	}})
	return mediaHarness{h: h, st: st}
}

// writeMediaFile writes content to a named file under a temp dir and returns
// its absolute path — the value the seeded document's path facts carry.
func writeMediaFile(t *testing.T, name, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), name)
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("write %s: %v", name, err)
	}
	return path
}

// seedMediaItem persists one item whose document carries the given path facts.
func (mh mediaHarness) seedMediaItem(t *testing.T, itemID, doc string) {
	t.Helper()
	libs, err := mh.st.ListLibraries(context.Background())
	if err != nil {
		t.Fatalf("ListLibraries: %v", err)
	}
	if len(libs) != 1 {
		t.Fatalf("libraries = %d, want 1 (one library per harness)", len(libs))
	}
	if err := mh.st.PutItem(context.Background(), store.Item{
		ID: itemID, ModuleID: "tv", LibraryID: libs[0].ID, FileID: "fid-" + itemID,
		RelativePath: itemID + ".mp4", MediaType: "movie",
		Document:      json.RawMessage(doc),
		SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem %s: %v", itemID, err)
	}
}

// authedGet fires one GET with the admin bearer token and returns the response.
func (mh mediaHarness) authedGet(t *testing.T, path string) *http.Response {
	t.Helper()
	return doRequest(t, mh.h, http.MethodGet, path, "", adminToken)
}

// bodyBytes drains and returns a response body.
func bodyBytes(t *testing.T, resp *http.Response) string {
	t.Helper()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read body: %v", err)
	}
	return string(b)
}

// TestItemMediaAuth proves the endpoint sits behind the same bearer gate as
// every /api/v1 route (spec: "Media sits behind the bearer gate"): no
// credentials → 401 before any handler logic runs; a valid token → 200 bytes.
func TestItemMediaAuth(t *testing.T) {
	mh := newMediaHarness(t)
	original := writeMediaFile(t, "cover.jpg", "jpeg-bytes-original")
	mh.seedMediaItem(t, "itm-auth", `{"parsed":{"absolute_path":"`+original+`"}}`)

	t.Run("no_token_is_401", func(t *testing.T) {
		resp := doRequest(t, mh.h, http.MethodGet, "/api/v1/items/itm-auth/media", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("status = %d, want %d (endpoint must never serve bytes unauthenticated)", resp.StatusCode, http.StatusUnauthorized)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unauthenticated" {
			t.Fatalf("error code = %q, want unauthenticated", eb.Error.Code)
		}
	})

	t.Run("valid_token_is_200", func(t *testing.T) {
		resp := mh.authedGet(t, "/api/v1/items/itm-auth/media")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if got := bodyBytes(t, resp); got != "jpeg-bytes-original" {
			t.Fatalf("body = %q, want the document-resolved file's exact bytes", got)
		}
	})
}

// TestItemMediaOriginal proves the serve semantics (spec: "Original bytes
// served with caching headers"): exact bytes, Content-Type by extension, a
// strong ETag, Cache-Control: private, immutable — and If-None-Match revalidates
// to 304. Non-image bytes carry Content-Disposition: attachment (video
// downloads, it does not stream).
func TestItemMediaOriginal(t *testing.T) {
	mh := newMediaHarness(t)
	original := writeMediaFile(t, "movie.mp4", "mp4-bytes-here")
	mh.seedMediaItem(t, "itm-original", `{"parsed":{"absolute_path":"`+original+`"}}`)

	resp := mh.authedGet(t, "/api/v1/items/itm-original/media")
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	if got := bodyBytes(t, resp); got != "mp4-bytes-here" {
		t.Fatalf("body = %q, want the file's exact bytes", got)
	}
	if ct := resp.Header.Get("Content-Type"); ct != "video/mp4" {
		t.Fatalf("Content-Type = %q, want video/mp4 (derived from the file extension)", ct)
	}
	etag := resp.Header.Get("ETag")
	if etag == "" {
		t.Fatal("ETag missing, want a strong entity tag")
	}
	if len(etag) >= 2 && etag[:2] == "W/" {
		t.Fatalf("ETag = %s, want strong (no W/ prefix)", etag)
	}
	if cc := resp.Header.Get("Cache-Control"); cc != "private, immutable" {
		t.Fatalf("Cache-Control = %q, want %q", cc, "private, immutable")
	}
	if cd := resp.Header.Get("Content-Disposition"); !strings.Contains(cd, "attachment") {
		t.Fatalf("Content-Disposition = %q, want attachment for non-image bytes (downloads-not-streams)", cd)
	}
	resp.Body.Close()

	// Conditional re-request with the returned ETag revalidates to 304.
	req := httptest.NewRequest(http.MethodGet, "/api/v1/items/itm-original/media", nil)
	req.Header.Set("Authorization", "Bearer "+adminToken)
	req.Header.Set("If-None-Match", etag)
	rec := httptest.NewRecorder()
	mh.h.ServeHTTP(rec, req)
	cond := rec.Result()
	defer cond.Body.Close()
	if cond.StatusCode != http.StatusNotModified {
		t.Fatalf("If-None-Match status = %d, want %d", cond.StatusCode, http.StatusNotModified)
	}
}

// TestItemMediaThumb proves the thumb variant (spec: "Thumb variant serves the
// frame-grabber grab"): ?variant=thumb serves the frame-grabber JPEG's exact
// bytes, and HEAD answers the same headers with no body.
func TestItemMediaThumb(t *testing.T) {
	mh := newMediaHarness(t)
	thumb := writeMediaFile(t, "thumb.jpg", "jpeg-thumb-bytes")
	mh.seedMediaItem(t, "itm-thumb",
		`{"parsed":{"absolute_path":"/nonexistent/original.mp4"},"sources":{"frame-grabber":{"thumbnail_path":"`+thumb+`"}}}`)

	resp := mh.authedGet(t, "/api/v1/items/itm-thumb/media?variant=thumb")
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("GET status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	if got := bodyBytes(t, resp); got != "jpeg-thumb-bytes" {
		t.Fatalf("body = %q, want the frame-grabber JPEG's exact bytes", got)
	}
	if ct := resp.Header.Get("Content-Type"); ct != "image/jpeg" {
		t.Fatalf("Content-Type = %q, want image/jpeg", ct)
	}
	if cc := resp.Header.Get("Cache-Control"); cc != "private, immutable" {
		t.Fatalf("Cache-Control = %q, want %q", cc, "private, immutable")
	}

	// HEAD answers the same headers, no body (stdlib ServeContent semantics
	// over the same header set the GET established).
	head := doRequest(t, mh.h, http.MethodHead, "/api/v1/items/itm-thumb/media?variant=thumb", "", adminToken)
	defer head.Body.Close()
	if head.StatusCode != http.StatusOK {
		t.Fatalf("HEAD status = %d, want %d", head.StatusCode, http.StatusOK)
	}
	if b, err := io.ReadAll(head.Body); err != nil || len(b) != 0 {
		t.Fatalf("HEAD body = %q (err %v), want empty", b, err)
	}
	for _, h := range []string{"Content-Type", "ETag", "Cache-Control", "Content-Disposition"} {
		if head.Header.Get(h) != resp.Header.Get(h) {
			t.Fatalf("HEAD %s = %q, want the GET value %q", h, head.Header.Get(h), resp.Header.Get(h))
		}
	}
}

// TestItemMediaErrors proves the error contract (spec: "Canonical errors and no
// client-steered paths"): unknown id / absent path fact / missing file → 404
// not_found; unknown variant → 400 bad_request; and no client-supplied
// path-like parameter ever steers resolution away from the stored document.
func TestItemMediaErrors(t *testing.T) {
	mh := newMediaHarness(t)
	original := writeMediaFile(t, "real.mp4", "document-resolved-bytes")
	mh.seedMediaItem(t, "itm-no-facts", `{}`)
	mh.seedMediaItem(t, "itm-missing-file", `{"parsed":{"absolute_path":"/nonexistent/dir/gone.mp4"}}`)
	mh.seedMediaItem(t, "itm-real", `{"parsed":{"absolute_path":"`+original+`"}}`)

	t.Run("unknown_id_404", func(t *testing.T) {
		resp := mh.authedGet(t, "/api/v1/items/itm-does-not-exist/media")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("no_path_fact_404", func(t *testing.T) {
		resp := mh.authedGet(t, "/api/v1/items/itm-no-facts/media")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("no_thumb_fact_404", func(t *testing.T) {
		resp := mh.authedGet(t, "/api/v1/items/itm-no-facts/media?variant=thumb")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d (no server-side fallback — D6)", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("missing_file_on_disk_404", func(t *testing.T) {
		resp := mh.authedGet(t, "/api/v1/items/itm-missing-file/media")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("unknown_variant_400", func(t *testing.T) {
		resp := mh.authedGet(t, "/api/v1/items/itm-real/media?variant=poster")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})

	t.Run("client_path_params_never_steer", func(t *testing.T) {
		// Path-like parameters are not resolution inputs: the bytes served are
		// the stored document's file, never the client-named path.
		resp := mh.authedGet(t, "/api/v1/items/itm-real/media?path=/etc/passwd&absolute_path=/etc/passwd&thumbnail_path=/etc/passwd")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if got := bodyBytes(t, resp); got != "document-resolved-bytes" {
			t.Fatalf("body = %q, want the document-resolved bytes (client path params ignored)", got)
		}
		// The same parameters on a fact-less item serve nothing: no fallback
		// onto the client-supplied path.
		resp2 := mh.authedGet(t, "/api/v1/items/itm-no-facts/media?path="+original)
		defer resp2.Body.Close()
		if resp2.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d (client-supplied path must not resolve)", resp2.StatusCode, http.StatusNotFound)
		}
	})
}
